// SPDX-License-Identifier: MIT
pragma solidity 0.8.19;

import ".deps/github/OpenZeppelin/openzeppelin-contracts/contracts/security/ReentrancyGuard.sol";
import ".deps/github/OpenZeppelin/openzeppelin-contracts/contracts/token/ERC777/ERC777.sol";
import ".deps/github/OpenZeppelin/openzeppelin-contracts/contracts/utils/Strings.sol";
import ".deps/github/dapphub/ds-math/src/math.sol";

contract UnifiedRedistributor_v5 is IERC777Recipient, DSMath, ReentrancyGuard {

    using Strings for uint256;

    address public owner;
    ERC777 public immutable token;

    // ===== RESERVES =====
    uint256 public reserve1;
    uint256 public reserve2;
    uint256 public reserve3;

    // ===== STATE =====
    uint256 public transfersCount;
    uint256 public transfersCount1;
    uint256 public transfersCount2;
    uint256 public transfersCount3;
    uint256 public cycleId1;
    uint256 public cycleId2;
    uint256 public cycleId3;

    uint256 public profit;

    // ===== RANDOM =====
    uint256 public randomNumber1;
    uint256 public randomNumber2;
    uint256 public randomNumber3;
    uint256 public randomNumber7;
    uint256 public randomNumber8;
    uint256 public randomNumber9;

    // ===== ENTROPY =====
    bytes32 private entropy1;
    bytes32 private entropy2;
    bytes32 private entropy3;

   // ===== EVENTS =====
    event Received(address indexed from, uint256 amount);
    event Redistributed(address indexed to, uint256 amount, uint8 reserveId);
    event CycleId(uint256 id);
    event B1RedistributionAttempt(address indexed sender, uint256 random1, uint256 random2, uint256 random3, uint256 sum, uint256 transferCount1, bool triggered, uint256 profitTransferred);
    event B2RedistributionAttempt(address indexed sender, uint256 random1, uint256 random2, uint256 random3, uint256 sum, uint256 transferCount2, bool triggered, uint256 profitTransferred);
    event B3RedistributionAttempt(address indexed sender, uint256 random1, uint256 random2, uint256 random3, uint256 sum1, uint256 sum2, uint256 transferCount3, bool triggered, uint256 profitTransferred);


    constructor(ERC777 _token) {
        IERC1820Registry(0x1820a4B7618BdE71Dce8cdc73aAB6C95905faD24)
            .setInterfaceImplementer(address(this), keccak256("ERC777TokensRecipient"), address(this));

        owner = msg.sender;
        token = _token;
        cycleId1 = 1;
        cycleId2 = 1;
        cycleId3 = 1;
    }

    modifier onlyValidToken() {
        require(msg.sender == address(token), "Invalid token");
        _;
    }

   function tokenBalance() public view returns(uint256) {
        return ERC777(token).balanceOf(address(this));
    }

    function getTransfersCount() public view returns (uint256) {
        return transfersCount;
    }
    
    function getTransfersCount1() public view returns (uint256) {
        return transfersCount1;
    }
    
    function getTransfersCount2() public view returns (uint256) {
        return transfersCount2;
    }

    function getTransfersCount3() public view returns (uint256) {
        return transfersCount3;
    }


    // ===== ENTROPY UPDATE =====
        function _updateEntropy1(
            address from,
            uint256 amount,
            bytes32 e1,
            bytes32 e2,
            bytes32 e3
        ) internal {
            entropy1 = keccak256(
                abi.encodePacked(
                    e1,
                    e2,
                    e3,
                    from,
                    amount,
                    block.prevrandao,
                    blockhash(block.number - 1),
                    block.number,
                    transfersCount1,
                    cycleId1
                )
            );
        }

        function _updateEntropy2(
            address from,
            uint256 amount,
            bytes32 e1,
            bytes32 e2,
            bytes32 e3
        ) internal {
            entropy2 = keccak256(
                abi.encodePacked(
                    e2,
                    e1,
                    e3,
                    from,
                    amount,
                    block.prevrandao,
                    blockhash(block.number - 1),
                    block.number,
                    transfersCount2,
                    cycleId2
                )
            );
        }

        function _updateEntropy3(
            address from,
            uint256 amount,
            bytes32 e1,
            bytes32 e2,
            bytes32 e3
        ) internal {
            entropy3 = keccak256(
                abi.encodePacked(
                    e3,
                    e1,
                    e2,
                    from,
                    amount,
                    block.prevrandao,
                    blockhash(block.number - 1),
                    block.number,
                    transfersCount3,
                    cycleId3
                )
            );
        }


    // ===== ERC777 ENTRY =====
    function tokensReceived(
        address,
        address from,
        address,
        uint256 amount,
        bytes calldata,
        bytes calldata
    ) external override onlyValidToken nonReentrant {

        require(from != address(0), "Invalid sender");


        emit Received(from, amount);

              
        bytes32 e1 = entropy1;
        bytes32 e2 = entropy2;
        bytes32 e3 = entropy3;

        // ===== UPDATE ENTROPY WITHOUT BIAS =====
        _updateEntropy1(from, amount, e1, e2, e3);
        _updateEntropy2(from, amount, e1, e2, e3);
        _updateEntropy3(from, amount, e1, e2, e3);
        // Split into reserves
        uint256 share = amount / 3;
        reserve1 += share;
        reserve2 += share;
        reserve3 += (amount - share * 2);
        // Increment transfers count
        transfersCount1++;
        transfersCount2++;
        transfersCount3++;
        // Process each reserve
        _processReserve1(from);
        _processReserve2(from);
        _processReserve3(from);
    }

    // =====================================================
    // ================= RESERVE 1 ==========================
    // =====================================================

    function _processReserve1(address from) internal {

        bool triggered = false;

        randomNumber1 = theRandomNumber1();
        randomNumber2 = theRandomNumber2();
        randomNumber3 = theRandomNumber3();
         transfersCount1++;

        uint256 sum = randomNumber1 + randomNumber2 + randomNumber3;

        if (sum == 88) {
            profit = wdiv(wmul(reserve1, 90), 100);
        } else if (sum < 20 && sum % 2 == 1) {
            profit = wdiv(wmul(reserve1, 60), 100);
        } else if (sum > 80 && sum % 2 == 0) {
            profit = wdiv(wmul(reserve1, 30), 100);
        } else {
            return;
        }
         reserve1 -= profit;
        _payout(from, profit, 1);
         triggered = true;
        reset1();
         emit B1RedistributionAttempt(from, randomNumber1, randomNumber2,randomNumber3, transfersCount1, sum, triggered, profit);
    }

    // =====================================================
    // ================= RESERVE 2 ==========================
    // =====================================================

    function _processReserve2(address from) internal {
        
        bool triggered = false;

        randomNumber1 = theRandomNumber1();
        randomNumber2 = theRandomNumber2();
        randomNumber3 = theRandomNumber3();
        transfersCount2++;
        uint256 sum = randomNumber1 + randomNumber2 + randomNumber3;

        if (transfersCount2 > 1000 && sum < 80 && sum % 2 == 0) {
            profit = wdiv(wmul(reserve2, 10), 100);
        } else if (transfersCount2 > 1000 && sum > 180 && sum % 2 == 1) {
            profit = wdiv(wmul(reserve2, 30), 100);
            } else if (transfersCount2 > 1000 && sum == 192) {
            profit = wdiv(wmul(reserve2, 90), 100);
        } else {
            return;
        }
          reserve2 -= profit;
        _payout(from, profit, 2);
        triggered = true;
        reset2();
        
       emit B2RedistributionAttempt(from, randomNumber1, randomNumber2,randomNumber3, transfersCount2, sum, triggered, profit);

    }

    // =====================================================
    // ================= RESERVE 3 ==========================
    // =====================================================

    function _processReserve3(address from) internal {
        
        bool triggered = false;

        randomNumber1 = theRandomNumber7();
        randomNumber2 = theRandomNumber8();
        randomNumber3 = theRandomNumber9();

        transfersCount3++;

        uint256 sum1 = randomNumber1 + randomNumber2 + randomNumber3 + transfersCount3;
        uint256 sum2 = randomNumber1 + randomNumber2 + randomNumber3;

        if (sum1 == 100000) {
            profit = wdiv(wmul(reserve3, 90), 100);
        } else if  (sum2 == 100000) {
            profit = wdiv(wmul(reserve3, 60), 100);
        } else if  (randomNumber1 < transfersCount3 && randomNumber2 < transfersCount3 && randomNumber3 < transfersCount3) {
            profit = wdiv(wmul(reserve3, 30), 100);
        } else {
            return;
        }
         reserve3 -= profit;
        _payout(from, profit, 3);
        triggered = true;
        reset3();
         emit B3RedistributionAttempt(from, randomNumber1, randomNumber2,randomNumber3, transfersCount3, sum1, sum2, triggered, profit);

    }

    // ===== PAYOUT =====
    function _payout(address to, uint256 amount, uint8 reserveId) internal {

        token.send(to, amount, "");
     
        emit Redistributed(to, amount, reserveId);

       }

    // =====================================================
    // ========== RANDOM GENERATORS =========================
    // =====================================================

    function theRandomNumber1() private view returns (uint256) {
        bytes32 random = keccak256(
            abi.encodePacked(
                entropy1,
                randomNumber5(),
                randomNumber4(),
                randomNumber6(),
                transfersCount2,
                cycleId1,
                blockhash(block.number-1)
            )
        );
        return uint256(random) % 66 + 2;
    }

    function theRandomNumber2() private view returns (uint256) {
        bytes32 random = keccak256(
            abi.encodePacked(
                entropy2,
                randomNumber5(),
                randomNumber6(),
                transfersCount1,
                cycleId3,
                blockhash(block.number-1)
            )
        );
        return uint256(random) % 66 + 2;
    }

    function theRandomNumber3() private view returns (uint256) {
        bytes32 random = keccak256(
            abi.encodePacked(
                entropy3,
                randomNumber4(),
                randomNumber6(),
                transfersCount3,
                cycleId2,
                blockhash(block.number-1)
            )
        );
        return uint256(random) % 66 + 2;
    }

    function randomNumber4() private view returns (uint256) {
        bytes32 random = keccak256(
            abi.encodePacked(
                entropy1,
                transfersCount3,
                owner,
                msg.sender,
                cycleId3,
                blockhash(block.number-1)
            )
        );
        return uint256(random) % 300000 + 2;
    }

    function randomNumber5() private view returns (uint256) {
        bytes32 random = keccak256(
            abi.encodePacked(
                entropy2,
                profit,
                owner,
                transfersCount1,
                cycleId2,
                blockhash(block.number-1)
            )
        );
        return uint256(random) % 600000 + 2;
    }

    function randomNumber6() private view returns (uint256) {
        bytes32 random = keccak256(
            abi.encodePacked(
                entropy3,
                cycleId1,
                transfersCount2,
                profit,
                blockhash(block.number-1)
            )
        );
        return uint256(random) % 900000 + 2;
    }
     function theRandomNumber7() private view returns (uint256) {
        bytes32 random = keccak256(
            abi.encodePacked(
                entropy3,
                randomNumber5(),
                randomNumber4(),
                randomNumber6(),
                transfersCount3,
                cycleId1,
                blockhash(block.number-1)
            )
        );
        return uint256(random) % 66000 + 2;
    }

    function theRandomNumber8() private view returns (uint256) {
        bytes32 random = keccak256(
            abi.encodePacked(
                entropy2,
                randomNumber5(),
                randomNumber6(),
                transfersCount2,
                cycleId2,
                blockhash(block.number-1)
            )
        );
        return uint256(random) % 66000 + 2;
    }

    function theRandomNumber9() private view returns (uint256) {
        bytes32 random = keccak256(
            abi.encodePacked(
                entropy1,
                randomNumber4(),
                randomNumber6(),
                transfersCount1,
                cycleId3,
                blockhash(block.number-1)
            )
        );
        return uint256(random) % 66000 + 2;
    }

       function reset1() internal {
        transfersCount1 = 0;
        cycleId1++;
        emit CycleId(cycleId1);
    }
      function reset2() internal {
        transfersCount2 = 0;
        cycleId2++;
        emit CycleId(cycleId2);
    }
      function reset3() internal {
        transfersCount3 = 0;
        cycleId3++;
        emit CycleId(cycleId3);
    }
}

